<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Think Ocean CMS</title><style>:root{--navy:#063f52;--teal:#00a9b5;--bg:#f3f7f8;--line:#d8e7e9;--muted:#60777e}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Arial,sans-serif;color:#16343d}.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.sidebar{background:var(--navy);color:#fff;padding:28px 22px}.sidebar h1{font-size:19px}.sidebar a{display:block;color:#d6eef1;padding:10px 0;text-decoration:none}.main{padding:32px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:26px}.top h2{margin:0;color:var(--navy)}.panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px;margin-bottom:24px;box-shadow:0 12px 30px #063f5208}.panel h3{margin-top:0;color:var(--navy)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field{display:grid;gap:7px}.full{grid-column:1/-1}label{font-size:13px;font-weight:800}input,textarea{width:100%;border:1px solid #bdd1d5;border-radius:9px;padding:11px;font:inherit}textarea{min-height:105px;resize:vertical}.button{border:0;border-radius:999px;padding:11px 20px;background:var(--teal);color:#fff;font-weight:800;cursor:pointer}.danger{background:#b42318}.status{padding:13px 16px;background:#e9f8ef;color:#176b39;border-radius:10px;margin-bottom:18px}.errors{padding:13px 16px;background:#fff0ef;color:#9d2118;border-radius:10px;margin-bottom:18px}.items{display:grid;gap:14px}.item{border:1px solid var(--line);border-radius:12px;padding:18px}.item-head{display:flex;justify-content:space-between;align-items:center}.badge{background:#e3f7f8;color:#08758b;border-radius:999px;padding:5px 10px;font-size:11px;font-weight:800}.muted{color:var(--muted);font-size:13px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:15px}@media(max-width:850px){.shell{grid-template-columns:1fr}.sidebar{padding:18px}.main{padding:18px}.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head>
